// Abstract DEX Subgraph API for dynamic pool discovery

// Subgraph URLs for Abstract testnet  
const V2_SUBGRAPH_URL = 'https://subgraph.satsuma-prod.com/bdd23fa2967b/mss/v2-testnet/api'
const V3_SUBGRAPH_URL = 'https://subgraph.satsuma-prod.com/bdd23fa2967b/mss/aborean-finance-v3-abstract-testnet/api'

// GraphQL queries based on tested schema
const V2_POOLS_QUERY = `
  query GetV2Pools($tokenIn: String!, $tokenOut: String!) {
    pairs(
      where: {
        or: [
          { token0: $tokenIn, token1: $tokenOut }
          { token0: $tokenOut, token1: $tokenIn }
        ]
      }
      orderBy: reserveUSD
      orderDirection: desc
    ) {
      id
      token0 {
        id
        symbol
        decimals
        name
      }
      token1 {
        id
        symbol
        decimals
        name
      }
      reserve0
      reserve1
      reserveUSD
      stable
    }
  }
`

const V2_MULTI_HOP_QUERY = `
  query GetV2MultiHopPools($tokens: [String!]!) {
    pairs(
      where: {
        and: [
          {
            or: [
              { token0_in: $tokens }
              { token1_in: $tokens }
            ]
          }
          { reserveUSD_gt: "100" }
        ]
      }
      first: 50
      orderBy: reserveUSD
      orderDirection: desc
    ) {
      id
      token0 {
        id
        symbol
        decimals
        name
      }
      token1 {
        id
        symbol
        decimals
        name
      }
      reserve0
      reserve1
      reserveUSD
      stable
    }
  }
`

const V3_POOLS_QUERY = `
  query GetV3Pools($tokenIn: String!, $tokenOut: String!) {
    pools(
      where: {
        or: [
          { token0: $tokenIn, token1: $tokenOut }
          { token0: $tokenOut, token1: $tokenIn }
        ]
      }
      orderBy: totalValueLockedUSD
      orderDirection: desc
    ) {
      id
      token0 {
        id
        symbol
        decimals
        name
      }
      token1 {
        id
        symbol
        decimals
        name
      }
      tickSpacing
      liquidity
      sqrtPrice
      tick
      totalValueLockedUSD
      totalValueLockedToken0
      totalValueLockedToken1
    }
  }
`

// Query to fetch top pools by TVL (for search modal)
const V2_TOP_POOLS_QUERY = `
  query GetTopV2Pools($first: Int!) {
    pairs(
      first: $first
      orderBy: reserveUSD
      orderDirection: desc
      where: { reserveUSD_gt: "1000" }
    ) {
      id
      token0 {
        id
        symbol
        decimals
        name
      }
      token1 {
        id
        symbol
        decimals
        name
      }
      reserve0
      reserve1
      reserveUSD
      stable
    }
  }
`

const V3_TOP_POOLS_QUERY = `
  query GetTopV3Pools($first: Int!) {
    pools(
      first: $first
      orderBy: totalValueLockedUSD
      orderDirection: desc
      where: { totalValueLockedUSD_gt: "1000" }
    ) {
      id
      token0 {
        id
        symbol
        decimals
        name
      }
      token1 {
        id
        symbol
        decimals
        name
      }
      tickSpacing
      liquidity
      sqrtPrice
      tick
      totalValueLockedUSD
      totalValueLockedToken0
      totalValueLockedToken1
    }
  }
`

// Types for subgraph responses
export interface V2PoolData {
  id: string
  token0: {
    id: string
    symbol: string
    decimals: string
    name: string
  }
  token1: {
    id: string
    symbol: string
    decimals: string
    name: string
  }
  reserve0: string // Already formatted (not raw wei)
  reserve1: string // Already formatted (not raw wei)
  reserveUSD: string
  stable?: boolean
}

export interface V3PoolData {
  id: string
  token0: {
    id: string
    symbol: string
    decimals: string
    name: string
  }
  token1: {
    id: string
    symbol: string
    decimals: string
    name: string
  }
  tickSpacing: string
  liquidity: string
  sqrtPrice: string
  tick: string
  totalValueLockedUSD: string
  totalValueLockedToken0: string
  totalValueLockedToken1: string
}

// Fetch V2 pools for specific token pair
export async function fetchV2Pools(tokenIn: string, tokenOut: string): Promise<V2PoolData[]> {
  try {
    const response = await fetch(V2_SUBGRAPH_URL, {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
      },
      body: JSON.stringify({
        query: V2_POOLS_QUERY,
        variables: { 
          tokenIn: tokenIn.toLowerCase(), 
          tokenOut: tokenOut.toLowerCase() 
        },
      }),
    })

    const data = await response.json()
    
    if (data.errors) {
      console.error('V2 Subgraph errors:', data.errors)
      return []
    }

    return data.data?.pairs || []
  } catch (error) {
    console.error('Failed to fetch V2 pools:', error)
    return []
  }
}

// Fetch V3 pools for specific token pair  
export async function fetchV3Pools(tokenIn: string, tokenOut: string): Promise<V3PoolData[]> {
  try {
    const response = await fetch(V3_SUBGRAPH_URL, {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
      },
      body: JSON.stringify({
        query: V3_POOLS_QUERY,
        variables: { 
          tokenIn: tokenIn.toLowerCase(), 
          tokenOut: tokenOut.toLowerCase() 
        },
      }),
    })

    const data = await response.json()
    
    if (data.errors) {
      console.error('V3 Subgraph errors:', data.errors)
      return []
    }

    return data.data?.pools || []
  } catch (error) {
    console.error('Failed to fetch V3 pools:', error)
    return []
  }
}

// Fetch pools for multi-hop routing including common base pairs
export async function fetchPoolsForRouting(
  tokenIn: string, 
  tokenOut: string,
  includeMultiHop = true
): Promise<{ v2Pools: V2PoolData[]; v3Pools: V3PoolData[] }> {

  // Common base tokens for multi-hop routing
  const COMMON_BASES = [
    '0x9edcde0257f2386ce177c3a7fcdd97787f0d841d', // WETH
    '0x698f98ab816670692fa9dd8e1486ea0fd253e996', // USDC
  ]

  const queries = []

  // Direct pairs
  queries.push(fetchV2Pools(tokenIn, tokenOut))
  queries.push(fetchV3Pools(tokenIn, tokenOut))

  // Multi-hop pairs if enabled
  if (includeMultiHop) {
    const relevantTokens = [tokenIn, tokenOut, ...COMMON_BASES]
      .map(t => t.toLowerCase())
      // Remove duplicates
      .filter((token, index, self) => self.indexOf(token) === index)
    
    // Fetch all pools involving these tokens for multi-hop
    queries.push(fetchV2MultiHopPools(relevantTokens))
  }

  try {
    const results = await Promise.all(queries)
    
    let v2Pools: V2PoolData[] = results[0] || []
    let v3Pools: V3PoolData[] = results[1] || []
    
    // Add multi-hop pools if available
    if (includeMultiHop && results[2]) {
      v2Pools = [...v2Pools, ...results[2]]
    }

    // Remove duplicates
    v2Pools = v2Pools.filter((pool, index, self) => 
      index === self.findIndex(p => p.id === pool.id)
    )
    v3Pools = v3Pools.filter((pool, index, self) => 
      index === self.findIndex(p => p.id === pool.id)
    )

    
    return { v2Pools, v3Pools }
  } catch (error) {
    console.error('Failed to fetch pools for routing:', error)
    return { v2Pools: [], v3Pools: [] }
  }
}

// Query to fetch single token data
const TOKEN_QUERY = `
  query GetToken($tokenAddress: String!) {
    tokens(where: { id: $tokenAddress }) {
      id
      symbol
      decimals
      name
    }
  }
`

// Fetch token data from Abstract subgraphs
export async function fetchTokenData(tokenAddress: string): Promise<{
  id: string
  symbol: string
  decimals: string
  name: string
} | null> {
  try {
    // Try V2 subgraph first
    const v2Response = await fetch(V2_SUBGRAPH_URL, {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
      },
      body: JSON.stringify({
        query: TOKEN_QUERY,
        variables: { tokenAddress: tokenAddress.toLowerCase() },
      }),
    })

    const v2Data = await v2Response.json()
    
    if (v2Data.data?.tokens?.[0]) {
      return v2Data.data.tokens[0]
    }

    // Try V3 subgraph as fallback
    const v3Response = await fetch(V3_SUBGRAPH_URL, {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
      },
      body: JSON.stringify({
        query: TOKEN_QUERY,
        variables: { tokenAddress: tokenAddress.toLowerCase() },
      }),
    })

    const v3Data = await v3Response.json()
    
    if (v3Data.data?.tokens?.[0]) {
      return v3Data.data.tokens[0]
    }

    return null
  } catch (error) {
    console.error('Failed to fetch token data from Abstract subgraphs:', error)
    return null
  }
}

// Helper function for multi-hop pool fetching
async function fetchV2MultiHopPools(tokens: string[]): Promise<V2PoolData[]> {
  try {
    const response = await fetch(V2_SUBGRAPH_URL, {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
      },
      body: JSON.stringify({
        query: V2_MULTI_HOP_QUERY,
        variables: { tokens },
      }),
    })

    const data = await response.json()
    
    if (data.errors) {
      console.error('V2 Multi-hop subgraph errors:', data.errors)
      return []
    }

    return data.data?.pairs || []
  } catch (error) {
    console.error('Failed to fetch V2 multi-hop pools:', error)
    return []
  }
}

// Fetch top pools by TVL for search modal
export async function fetchTopPoolsByTVL(limit: number = 15): Promise<{
  v2Pools: V2PoolData[]
  v3Pools: V3PoolData[]
}> {
  try {
    const [v2Response, v3Response] = await Promise.all([
      fetch(V2_SUBGRAPH_URL, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify({
          query: V2_TOP_POOLS_QUERY,
          variables: { first: Math.ceil(limit * 0.6) }, // 60% V2 pools
        }),
      }),
      fetch(V3_SUBGRAPH_URL, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify({
          query: V3_TOP_POOLS_QUERY,
          variables: { first: Math.ceil(limit * 0.4) }, // 40% V3 pools
        }),
      }),
    ])

    const [v2Data, v3Data] = await Promise.all([
      v2Response.json(),
      v3Response.json(),
    ])

    if (v2Data.errors) {
      console.error('V2 Top pools subgraph errors:', v2Data.errors)
    }

    if (v3Data.errors) {
      console.error('V3 Top pools subgraph errors:', v3Data.errors)
    }

    const v2Pools: V2PoolData[] = v2Data.data?.pairs || []
    const v3Pools: V3PoolData[] = v3Data.data?.pools || []

    return { v2Pools, v3Pools }
  } catch (error) {
    console.error('Failed to fetch top pools by TVL:', error)
    return { v2Pools: [], v3Pools: [] }
  }
}