"use strict";
import { useQuery } from "@tanstack/react-query";
const GET_ALL_V2_POOLS = `
  query GetAllV2Pools {
    pairs {
      id
      token0 {
        id
        symbol
        decimals
        name
      }
      token1 {
        id
        symbol
        decimals
        name
      }
      reserve0
      reserve1
      totalSupply
      stable
    }
  }
`;
const GET_ALL_V3_POOLS = `
  query GetAllV3Pools {
    pools {
      id
      token0 {
        id
        symbol
        decimals
        name
      }
      token1 {
        id
        symbol
        decimals
        name
      }
      tickSpacing
      liquidity
      sqrtPrice
      tick
      totalValueLockedUSD
    }
  }
`;
const GET_USER_GAUGE_STAKES = `
  query GetUserGaugeStakes($userAddress: String!) {
    gaugeStakes(where: { user: $userAddress }) {
      id
      amount
      gauge {
        id
        pool
      }
      user
    }
  }
`;
const V2_SUBGRAPH_URL = "https://subgraph.satsuma-prod.com/bdd23fa2967b/mss/v2-testnet/api";
const V3_SUBGRAPH_URL = "https://subgraph.satsuma-prod.com/bdd23fa2967b/mss/aborean-finance-v3-abstract-testnet/api";
const GAUGES_SUBGRAPH_URL = "https://subgraph.satsuma-prod.com/bdd23fa2967b/mss/abx-gauges/api";
async function fetchFromSubgraph(query, url, variables) {
  try {
    const response = await fetch(url, {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ query, variables })
    });
    const data = await response.json();
    if (data.errors) {
      console.error("Subgraph query errors:", data.errors);
      return null;
    }
    return data.data;
  } catch (error) {
    console.error("Subgraph fetch failed:", error);
    return null;
  }
}
async function fetchAllPoolData(userAddress) {
  try {
    console.log("\u{1F50D} Fetching pool data from subgraphs...");
    const [v2Data, v3Data, gaugeData] = await Promise.all([
      fetchFromSubgraph(
        GET_ALL_V2_POOLS,
        V2_SUBGRAPH_URL
      ),
      fetchFromSubgraph(
        GET_ALL_V3_POOLS,
        V3_SUBGRAPH_URL
      ),
      userAddress ? fetchFromSubgraph(
        GET_USER_GAUGE_STAKES,
        GAUGES_SUBGRAPH_URL,
        { userAddress: userAddress.toLowerCase() }
      ) : Promise.resolve(null)
    ]);
    const result = {
      v2Pools: v2Data?.pairs || [],
      v3Pools: v3Data?.pools || [],
      gaugeStakes: gaugeData?.gaugeStakes || []
    };
    console.log(`\u2705 Fetched ${result.v2Pools.length} V2 + ${result.v3Pools.length} V3 pools + ${result.gaugeStakes.length} gauge stakes`);
    return result;
  } catch (error) {
    console.error("\u274C Pool data fetch failed:", error);
    return { v2Pools: [], v3Pools: [], gaugeStakes: [] };
  }
}
export function usePoolData(userAddress) {
  return useQuery({
    queryKey: ["pool-data-simple", userAddress],
    queryFn: () => fetchAllPoolData(userAddress),
    staleTime: 6e4,
    // 1 minute
    refetchInterval: 12e4,
    // 2 minutes
    retry: (failureCount, error) => {
      if (error?.message?.includes("429")) return failureCount < 2;
      return failureCount < 3;
    },
    retryDelay: (attemptIndex) => Math.min(1e3 * 2 ** attemptIndex, 3e4)
  });
}
