"use strict";
import { useMenuContent } from "components/NavBar/CompanyMenu/Content";
import { NavDropdown } from "components/NavBar/NavDropdown";
import { Link } from "react-router-dom";
import { Flex, Text, styled } from "ui/src";
import { TestID } from "uniswap/src/test/fixtures/testIDs";
const Container = styled(Flex, {
  width: "180px",
  p: "$gap4",
  userSelect: "none",
  height: "unset",
  borderRadius: "$rounded12",
  borderColor: "$surface2Hovered"
  // backgroundColor: '$slate',
});
const LinkStyle = {
  textDecoration: "none",
  height: "unset",
  padding: 0
};
export function MenuLink({
  title,
  href,
  icon,
  closeMenu,
  textVariant = "subheading2"
}) {
  return <Link to={href} onClick={closeMenu} style={LinkStyle}>
      <Flex
    py={"$spacing12"}
    px={"$spacing12"}
    borderRadius={"$rounded12"}
    hoverStyle={{ backgroundColor: "$surface2" }}
    transition='background-color 0.2s ease'
    row
    alignItems="center"
    gap="$gap8"
  >
        {icon}
        <Text variant={textVariant} color={"$neutral2"}>
          {title}
        </Text>
      </Flex>
    </Link>;
}
export function MenuDropdown({ close }) {
  const menuContent = useMenuContent();
  return <NavDropdown isOpen={false} dataTestId={TestID.NavCompanyDropdown}>
      <Container>
        <Flex gap="$spacing4">
          {menuContent.map((item, index) => <MenuLink
    key={`${item.title}_${index}}`}
    title={item.title}
    href={item.href}
    icon={item.icon}
    closeMenu={close}
    internal={true}
  />)}
        </Flex>
      </Container>
    </NavDropdown>;
}
