"use strict";
import { useQuery } from "@tanstack/react-query";
import { Contract } from "@ethersproject/contracts";
import { useAccount } from "hooks/useAccount";
import { useEthersProvider } from "hooks/useEthersProvider";
import { getAbstractContracts } from "uniswap/src/constants/abstractContracts";
import { UniverseChainId } from "uniswap/src/features/chains/types";
import { usePoolData } from "./services/PoolDataService";
import { MulticallManager } from "./services/MulticallManager";
import { V2PositionService } from "./services/V2PositionService";
import { V3PositionService } from "./services/V3PositionService";
import { StakedV3PositionService } from "./services/StakedV3PositionService";
import { StakedV2PositionService } from "./services/StakedV2PositionService";
import { V2PositionDeduplicator } from "./services/V2PositionDeduplicator";
const MULTICALL3_ADDRESS = "0xcA11bde05977b3631167028862bE2a173976CA11";
const MULTICALL3_ABI = [
  {
    inputs: [{ components: [{ name: "target", type: "address" }, { name: "callData", type: "bytes" }], name: "calls", type: "tuple[]" }],
    name: "aggregate",
    outputs: [{ name: "blockNumber", type: "uint256" }, { name: "returnData", type: "bytes[]" }],
    stateMutability: "payable",
    type: "function"
  },
  {
    inputs: [
      { name: "requireSuccess", type: "bool" },
      { components: [{ name: "target", type: "address" }, { name: "callData", type: "bytes" }], name: "calls", type: "tuple[]" }
    ],
    name: "tryAggregate",
    outputs: [{ components: [{ name: "success", type: "bool" }, { name: "returnData", type: "bytes" }], name: "returnData", type: "tuple[]" }],
    stateMutability: "payable",
    type: "function"
  }
];
export function useSimpleAbstractPositions({
  address,
  chainIds,
  positionStatuses,
  protocolVersions
}) {
  const account = useAccount();
  const chainId = chainIds && chainIds.filter((c) => c != null)[0] || UniverseChainId.Sepolia;
  const provider = useEthersProvider({ chainId });
  const contracts = getAbstractContracts(chainId);
  const walletAddress = address || account.address;
  const { data: poolData, isLoading: poolsLoading } = usePoolData(walletAddress);
  const positionsQuery = useQuery({
    queryKey: ["positions-service-oriented", walletAddress, chainId, !!poolData, positionStatuses, protocolVersions],
    queryFn: async () => {
      if (!walletAddress || !provider || !poolData || !contracts) return [];
      try {
        const multicall = new Contract(MULTICALL3_ADDRESS, MULTICALL3_ABI, provider);
        const multicallManager = new MulticallManager(multicall);
        const v2Service = new V2PositionService(
          multicallManager,
          chainId,
          walletAddress,
          provider
        );
        const v3Service = new V3PositionService(
          multicallManager,
          chainId,
          walletAddress,
          contracts.nonfungiblePositionManager,
          provider
        );
        const stakedV3Service = new StakedV3PositionService(
          multicallManager,
          v3Service,
          walletAddress,
          provider
        );
        const stakedV2Service = new StakedV2PositionService(
          multicallManager,
          chainId,
          walletAddress,
          provider
        );
        const [v2Positions, v3Positions, stakedV3Positions, stakedV2Positions] = await Promise.all([
          v2Service.fetchPositions(poolData.v2Pools, protocolVersions),
          v3Service.fetchPositions(poolData.v3Pools, protocolVersions),
          stakedV3Service.fetchPositions(poolData.v3Pools, protocolVersions),
          stakedV2Service.fetchPositions(poolData.v2Pools, poolData.gaugeStakes, protocolVersions)
        ]);
        const stakedV3TokenIds = new Set(stakedV3Positions.map((p) => p.tokenId));
        const dedupedV3Positions = v3Positions.filter((p) => !stakedV3TokenIds.has(p.tokenId));
        const allPositionsBeforeDedup = [...v2Positions, ...dedupedV3Positions, ...stakedV3Positions, ...stakedV2Positions];
        const allPositions = V2PositionDeduplicator.deduplicatePositions(allPositionsBeforeDedup);
        const filteredPositions = applyFilters(allPositions, {
          positionStatuses,
          protocolVersions
        });
        return filteredPositions;
      } catch (error) {
        console.error("\u274C [POSITIONS] Service-oriented fetch failed:", error);
        return [];
      }
    },
    enabled: !!walletAddress && !!provider && !!poolData && !!contracts,
    staleTime: 3e4,
    // 30 seconds
    refetchInterval: 6e4,
    // 1 minute
    retry: 2
  });
  return {
    data: positionsQuery.data ? {
      pages: [{ positions: positionsQuery.data }]
    } : void 0,
    isLoading: poolsLoading || positionsQuery.isLoading,
    isPlaceholderData: positionsQuery.isPlaceholderData,
    refetch: positionsQuery.refetch,
    isFetching: positionsQuery.isFetching,
    // Pagination methods (not needed for service-oriented approach but kept for compatibility)
    fetchNextPage: () => Promise.resolve(),
    hasNextPage: false
  };
}
function applyFilters(positions, filters) {
  let filtered = positions;
  if (filters.positionStatuses && filters.positionStatuses.length > 0) {
    filtered = filtered.filter(
      (position) => filters.positionStatuses.includes(position.status)
    );
  }
  if (filters.protocolVersions && filters.protocolVersions.length > 0) {
    filtered = filtered.filter(
      (position) => filters.protocolVersions.includes(position.version)
    );
  }
  return filtered;
}
