import { useMemo } from 'react'
import { getAbstractTokenList } from 'uniswap/src/constants/tokens'
import { getTokenLogoUrl } from 'uniswap/src/constants/tokenLogos'
import { ProtectionResult } from 'uniswap/src/data/graphql/uniswap-data-api/__generated__/types-and-hooks'
import { UniverseChainId } from 'uniswap/src/features/chains/types'
import { CurrencyInfo, TokenList } from 'uniswap/src/features/dataApi/types'
import { buildCurrencyInfo } from 'uniswap/src/features/dataApi/utils'
import { currencyId } from 'uniswap/src/utils/currencyId'

export function useTrendingTokensCurrencyInfos(
  chainFilter: Maybe<UniverseChainId>,
  skip?: boolean,
): {
  data: CurrencyInfo[] | undefined
  error: Error | undefined
  refetch: () => void
  loading: boolean
} {
  // Return hardcoded Abstract tokens instead of making external API calls
  const formattedTokens = useMemo(() => {
    if (skip) return undefined

    const targetChainId = chainFilter || UniverseChainId.Sepolia // Default to testnet
    const tokens = getAbstractTokenList(targetChainId)
    
    return tokens.map(token => 
      buildCurrencyInfo({
        currency: token,
        currencyId: currencyId(token),
        logoUrl: getTokenLogoUrl(token.address),
        safetyInfo: {
          tokenList: TokenList.Default,
          protectionResult: ProtectionResult.Benign,
        },
      })
    ).filter((t): t is CurrencyInfo => Boolean(t))
  }, [chainFilter, skip])

  const refetch = () => {
    // No-op since we're using hardcoded data
  }

  return { 
    data: formattedTokens, 
    loading: false, 
    error: undefined, 
    refetch 
  }
}
