"use strict";
import { Contract } from "@ethersproject/contracts";
import { ProtocolVersion } from "@uniswap/client-pools/dist/pools/v1/types_pb";
import ERC20_ABI from "uniswap/src/abis/erc20.json";
import { PositionFactory } from "./PositionFactory";
const ABSTRACT_POOL_ABI = [
  {
    inputs: [],
    name: "index0",
    outputs: [{ internalType: "uint256", name: "", type: "uint256" }],
    stateMutability: "view",
    type: "function"
  },
  {
    inputs: [],
    name: "index1",
    outputs: [{ internalType: "uint256", name: "", type: "uint256" }],
    stateMutability: "view",
    type: "function"
  },
  {
    inputs: [{ internalType: "address", name: "", type: "address" }],
    name: "supplyIndex0",
    outputs: [{ internalType: "uint256", name: "", type: "uint256" }],
    stateMutability: "view",
    type: "function"
  },
  {
    inputs: [{ internalType: "address", name: "", type: "address" }],
    name: "supplyIndex1",
    outputs: [{ internalType: "uint256", name: "", type: "uint256" }],
    stateMutability: "view",
    type: "function"
  },
  {
    inputs: [{ internalType: "address", name: "", type: "address" }],
    name: "claimable0",
    outputs: [{ internalType: "uint256", name: "", type: "uint256" }],
    stateMutability: "view",
    type: "function"
  },
  {
    inputs: [{ internalType: "address", name: "", type: "address" }],
    name: "claimable1",
    outputs: [{ internalType: "uint256", name: "", type: "uint256" }],
    stateMutability: "view",
    type: "function"
  },
  {
    inputs: [],
    name: "tokens",
    outputs: [{ internalType: "address", name: "", type: "address" }, { internalType: "address", name: "", type: "address" }],
    stateMutability: "view",
    type: "function"
  }
];
export class V2PositionService {
  constructor(multicallManager, chainId, walletAddress, provider) {
    this.multicallManager = multicallManager;
    this.chainId = chainId;
    this.walletAddress = walletAddress;
    this.erc20Interface = new Contract("0x0000000000000000000000000000000000000000", ERC20_ABI, provider).interface;
    this.poolInterface = new Contract("0x0000000000000000000000000000000000000000", ABSTRACT_POOL_ABI, provider).interface;
  }
  erc20Interface;
  poolInterface;
  /**
   * Fetch all V2 positions for the user
   */
  async fetchPositions(v2Pools, protocolVersions) {
    if (!this.shouldFetchV2(v2Pools, protocolVersions)) {
      return [];
    }
    const calls = this.buildV2Calls(v2Pools);
    const results = await this.multicallManager.executeBatched(calls, 80);
    return this.processV2Results(results, v2Pools);
  }
  shouldFetchV2(v2Pools, protocolVersions) {
    return v2Pools.length > 0 && (!protocolVersions || protocolVersions.includes(ProtocolVersion.V2));
  }
  /**
   * Build multicall data for all V2 pools
   */
  buildV2Calls(pools) {
    const calls = [];
    pools.forEach((pool) => {
      calls.push({
        target: pool.id,
        callData: this.erc20Interface.encodeFunctionData("balanceOf", [this.walletAddress])
      });
      calls.push({
        target: pool.id,
        callData: this.poolInterface.encodeFunctionData("index0", [])
      });
      calls.push({
        target: pool.id,
        callData: this.poolInterface.encodeFunctionData("index1", [])
      });
      calls.push({
        target: pool.id,
        callData: this.poolInterface.encodeFunctionData("supplyIndex0", [this.walletAddress])
      });
      calls.push({
        target: pool.id,
        callData: this.poolInterface.encodeFunctionData("supplyIndex1", [this.walletAddress])
      });
      calls.push({
        target: pool.id,
        callData: this.poolInterface.encodeFunctionData("claimable0", [this.walletAddress])
      });
      calls.push({
        target: pool.id,
        callData: this.poolInterface.encodeFunctionData("claimable1", [this.walletAddress])
      });
      calls.push({
        target: pool.id,
        callData: this.poolInterface.encodeFunctionData("tokens", [])
      });
    });
    return calls;
  }
  /**
   * Process multicall results into PositionInfo objects
   */
  processV2Results(results, pools) {
    const positions = [];
    const callsPerPool = 8;
    for (let i = 0; i < pools.length; i++) {
      const pool = pools[i];
      const resultOffset = i * callsPerPool;
      try {
        if (resultOffset + callsPerPool > results.length) {
          console.warn(`[V2] Insufficient results for pool ${pool.id}`);
          continue;
        }
        const balance = this.erc20Interface.decodeFunctionResult("balanceOf", results[resultOffset])[0];
        const index0 = this.poolInterface.decodeFunctionResult("index0", results[resultOffset + 1])[0];
        const index1 = this.poolInterface.decodeFunctionResult("index1", results[resultOffset + 2])[0];
        const supplyIndex0 = this.poolInterface.decodeFunctionResult("supplyIndex0", results[resultOffset + 3])[0];
        const supplyIndex1 = this.poolInterface.decodeFunctionResult("supplyIndex1", results[resultOffset + 4])[0];
        const claimable0 = this.poolInterface.decodeFunctionResult("claimable0", results[resultOffset + 5])[0];
        const claimable1 = this.poolInterface.decodeFunctionResult("claimable1", results[resultOffset + 6])[0];
        if (balance.eq(0)) {
          continue;
        }
        let pendingFees0 = "0";
        let pendingFees1 = "0";
        try {
          if (supplyIndex0.gt(0) && index0.gt(supplyIndex0)) {
            const indexDiff0 = index0.sub(supplyIndex0);
            pendingFees0 = balance.mul(indexDiff0).div("1000000000000000000").toString();
          }
          if (supplyIndex1.gt(0) && index1.gt(supplyIndex1)) {
            const indexDiff1 = index1.sub(supplyIndex1);
            pendingFees1 = balance.mul(indexDiff1).div("1000000000000000000").toString();
          }
        } catch (e) {
          console.warn(`[V2] Fee calculation failed for pool ${pool.id}:`, e);
        }
        const totalFees0 = claimable0.add(pendingFees0 || "0").toString();
        const totalFees1 = claimable1.add(pendingFees1 || "0").toString();
        const position = PositionFactory.createV2Position({
          poolData: pool,
          balance: balance.toString(),
          claimable0: totalFees0,
          claimable1: totalFees1,
          chainId: this.chainId,
          walletAddress: this.walletAddress
        });
        positions.push(position);
      } catch (error) {
        console.error(`[V2] Failed to process pool ${pool.id}:`, error);
      }
    }
    return positions;
  }
}
