"use strict";
import { DollarSign, Lock } from "react-feather";
import { useLocation } from "react-router-dom";
import { useSporeColors } from "ui/src";
import { Hub, PapersText, Swap, VoteIcon } from "ui/src/components/icons";
export const useMenuContent = () => {
  const props = {
    size: 20,
    color: useSporeColors().neutral2.val
  };
  const { pathname } = useLocation();
  return [
    {
      title: "Dashboard",
      href: "/dash",
      icon: <PapersText {...props} />,
      isActive: pathname.startsWith("/dash")
    },
    // {
    //   title: 'Explore',
    //   href: '/explore',
    //   icon: <Explore {...props} />,
    //   isActive: pathname.startsWith('/explore') || pathname.startsWith('/nfts'),
    // },
    {
      title: "Trade",
      href: "/swap",
      icon: <Swap {...props} />,
      isActive: pathname.startsWith("/swap") || pathname.startsWith("/limit") || pathname.startsWith("/send")
    },
    {
      title: "Liquidity",
      href: "/liquidity",
      icon: <Hub {...props} />,
      isActive: pathname.startsWith("/liquidity")
    },
    {
      title: "Lock",
      href: "/locks",
      icon: <Lock {...props} />,
      isActive: pathname.startsWith("/lock")
    },
    {
      title: "Vote",
      href: "/vote",
      icon: <VoteIcon {...props} />,
      isActive: pathname.startsWith("/vote")
    },
    {
      title: "Incentives",
      href: "/incentives",
      icon: <DollarSign {...props} />,
      isActive: pathname.startsWith("/incentives")
    }
  ];
};
