"use strict";
import { Contract } from "@ethersproject/contracts";
import { ProtocolVersion } from "@uniswap/client-pools/dist/pools/v1/types_pb";
export class StakedV3PositionService {
  constructor(multicallManager, v3PositionService, walletAddress, provider) {
    this.multicallManager = multicallManager;
    this.v3PositionService = v3PositionService;
    this.walletAddress = walletAddress;
    this.gaugeInterface = new Contract("0x0000000000000000000000000000000000000000", [
      {
        inputs: [{ internalType: "address", name: "depositor", type: "address" }],
        name: "stakedLength",
        outputs: [{ internalType: "uint256", name: "", type: "uint256" }],
        stateMutability: "view",
        type: "function"
      },
      {
        inputs: [
          { internalType: "address", name: "depositor", type: "address" },
          { internalType: "uint256", name: "index", type: "uint256" }
        ],
        name: "stakedByIndex",
        outputs: [{ internalType: "uint256", name: "", type: "uint256" }],
        stateMutability: "view",
        type: "function"
      }
    ], provider).interface;
  }
  gaugeInterface;
  /**
   * Fetch all V3 positions staked in gauge contracts
   */
  async fetchPositions(v3Pools, protocolVersions) {
    if (!this.shouldFetchStakedV3(v3Pools, protocolVersions)) {
      return [];
    }
    try {
      const gaugeAddresses = await this.discoverGaugeAddresses(v3Pools);
      if (gaugeAddresses.length === 0) {
        return [];
      }
      const stakedTokenData = await this.getStakedTokenIds(gaugeAddresses);
      if (stakedTokenData.length === 0) {
        return [];
      }
      const gaugeDataMap = {};
      stakedTokenData.forEach(({ tokenId, gaugeAddress }) => {
        gaugeDataMap[tokenId] = { gaugeAddress, isStaked: true };
      });
      const tokenIds = stakedTokenData.map((d) => d.tokenId);
      const positions = await this.v3PositionService.processPositionDetails(tokenIds, v3Pools, gaugeDataMap);
      return positions;
    } catch (error) {
      console.error("\u274C [STAKED V3] Failed to fetch staked V3 positions:", error);
      return [];
    }
  }
  shouldFetchStakedV3(v3Pools, protocolVersions) {
    return v3Pools.length > 0 && (!protocolVersions || protocolVersions.includes(ProtocolVersion.V3));
  }
  /**
   * Discover gauge addresses from the gauges subgraph
   */
  async discoverGaugeAddresses(v3Pools) {
    try {
      const GAUGES_SUBGRAPH_URL = "https://subgraph.satsuma-prod.com/bdd23fa2967b/mss/abx-3-gauges/api";
      const poolIds = v3Pools.map((p) => p.id.toLowerCase());
      const response = await fetch(GAUGES_SUBGRAPH_URL, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          query: `
            query GetGaugesForPools($poolIds: [String!]) {
              gauges(
                first: 100, 
                where: { 
                  isAlive: true,
                  poolType: "V3",
                  pool_in: $poolIds
                }
              ) {
                id
                pool
              }
            }
          `,
          variables: { poolIds }
        })
      });
      if (!response.ok) {
        throw new Error(`HTTP ${response.status}: ${response.statusText}`);
      }
      const data = await response.json();
      if (data.errors) {
        console.error("[STAKED V3] GraphQL errors:", data.errors);
        throw new Error(`GraphQL errors: ${JSON.stringify(data.errors)}`);
      }
      const gauges = data.data?.gauges || [];
      const gaugeAddresses = gauges.map((g) => g.id).filter(
        (addr) => addr && addr !== "0x0000000000000000000000000000000000000000"
      );
      if (gaugeAddresses.length > 0) {
        return gaugeAddresses;
      }
      return ["0x9A414eC8f5807b11284ad45d0766C481694240bb"];
    } catch (e) {
      console.warn("[STAKED V3] Failed to query gauge addresses from subgraph, using fallback:", e);
      return ["0x9A414eC8f5807b11284ad45d0766C481694240bb"];
    }
  }
  /**
   * Get all staked token IDs from gauge contracts
   */
  async getStakedTokenIds(gaugeAddresses) {
    const stakedLengthCalls = gaugeAddresses.map((gaugeAddress) => ({
      target: gaugeAddress,
      callData: this.gaugeInterface.encodeFunctionData("stakedLength", [this.walletAddress])
    }));
    const stakedLengthResults = await this.multicallManager.execute(stakedLengthCalls);
    const tokenIdCalls = [];
    stakedLengthResults.forEach((result, gaugeIndex) => {
      const stakedLength = this.gaugeInterface.decodeFunctionResult("stakedLength", result)[0].toNumber();
      for (let i = 0; i < stakedLength; i++) {
        tokenIdCalls.push({
          target: gaugeAddresses[gaugeIndex],
          callData: this.gaugeInterface.encodeFunctionData("stakedByIndex", [this.walletAddress, i]),
          gaugeAddress: gaugeAddresses[gaugeIndex],
          index: i
        });
      }
    });
    if (tokenIdCalls.length === 0) {
      return [];
    }
    const tokenIdResults = await this.multicallManager.execute(
      tokenIdCalls.map((call) => ({ target: call.target, callData: call.callData }))
    );
    const stakedTokenData = [];
    tokenIdResults.forEach((result, idx) => {
      const tokenId = this.gaugeInterface.decodeFunctionResult("stakedByIndex", result)[0].toString();
      stakedTokenData.push({
        tokenId,
        gaugeAddress: tokenIdCalls[idx].gaugeAddress
      });
    });
    return stakedTokenData;
  }
}
