// Token logo URL mappings for Abstract DEX
// Using token addresses as keys (lowercase)

export const ABSTRACT_TOKEN_LOGOS: Record<string, string> = {
  // Abstract Testnet logos
  '0x9edcde0257f2386ce177c3a7fcdd97787f0d841d': '/images/tokens/eth-logo.png', // WETH
  '0x698f98ab816670692fa9dd8e1486ea0fd253e996': 'https://ethereum-optimism.github.io/data/USDC/logo.png', // USDC
  '0xb6313be1c20dc222199ec567951abc6b5b64dfd6': '/images/tokens/abx-logo.png', // ABX (local logo)
  '0xfaf7f84baacf74d9b6b70f201479d792e936f8a5': 'https://ethereum-optimism.github.io/data/USDT/logo.png', // USDT
  
  // Abstract Mainnet logos (when available)
  // Add mainnet token addresses here when they're deployed
}

export function getTokenLogoUrl(address: string): string | null {
  const normalizedAddress = address.toLowerCase()
  return ABSTRACT_TOKEN_LOGOS[normalizedAddress] || null
}